TESTPLAN_COLUMNS = [
    "Index", "SS / Module", "Feature", "Test Case Name", "Test Description",
    "Speed", "Mode", "Memory Start Offset", "Memory End Offset", "Remarks",
    "Test Steps / Procedure", "Impacted Registers", "Validation / Acceptance Criteria",
    "Code Generation"
]

METADATA_COLUMNS = [
    "Index", "Test Case Name", "Meta Test Description", "Meta Test Steps / Procedure",
    "Meta Impacted Registers", "Meta Validation / Acceptance Criteria",
    "Meta Headers", "Meta Macros", "Meta Arrays"
]

def generate_xlsx(output_path):
    """Generate the PCIE TestPlan XLSX workbook."""
    wb = Workbook()

    # ---- TestPlan Sheet ----
    ws_tp = wb.active
    ws_tp.title = "TestPlan"

    # Header formatting
    header_font = Font(name='Calibri', bold=True, color='FFFFFF', size=11)
    header_fill = PatternFill(start_color='4472C4', end_color='4472C4', fill_type='solid')
    header_align = Alignment(horizontal='center', vertical='center', wrap_text=True)
    cell_align = Alignment(vertical='top', wrap_text=True)
    thin_border = Border(
        left=Side(style='thin'), right=Side(style='thin'),
        top=Side(style='thin'), bottom=Side(style='thin')
    )

    # Write TestPlan headers
    for col_idx, col_name in enumerate(TESTPLAN_COLUMNS, 1):
        cell = ws_tp.cell(row=1, column=col_idx, value=col_name)
        cell.font = header_font
        cell.fill = header_fill
        cell.alignment = header_align
        cell.border = thin_border

    # Write TestPlan data rows
    for row_idx, row_data in enumerate(json_data, 2):
        for col_idx, col_name in enumerate(TESTPLAN_COLUMNS, 1):
            value = row_data.get(col_name, "")
            if value is None:
                value = ""
            cell = ws_tp.cell(row=row_idx, column=col_idx, value=str(value))
            cell.alignment = cell_align
            cell.border = thin_border

    # Freeze first row
    ws_tp.freeze_panes = 'A2'

    # Auto-size columns
    for col_idx, col_name in enumerate(TESTPLAN_COLUMNS, 1):
        max_len = len(col_name)
        for row_idx in range(2, len(json_data) + 2):
            cell_val = str(ws_tp.cell(row=row_idx, column=col_idx).value or "")
            lines = cell_val.split('\n')
            for line in lines:
                if len(line) > max_len:
                    max_len = len(line)
        adjusted_width = min(max_len + 4, 80)
        ws_tp.column_dimensions[get_column_letter(col_idx)].width = max(adjusted_width, 12)

    # ---- MetaData Sheet ----
    ws_md = wb.create_sheet(title="MetaData")

    # Write MetaData headers
    for col_idx, col_name in enumerate(METADATA_COLUMNS, 1):
        cell = ws_md.cell(row=1, column=col_idx, value=col_name)
        cell.font = header_font
        cell.fill = header_fill
        cell.alignment = header_align
        cell.border = thin_border

    # Write MetaData data rows
    for row_idx, row_data in enumerate(json_data, 2):
        for col_idx, col_name in enumerate(METADATA_COLUMNS, 1):
            value = row_data.get(col_name, "")
            if value is None:
                value = ""
            cell = ws_md.cell(row=row_idx, column=col_idx, value=str(value))
            cell.alignment = cell_align
            cell.border = thin_border

    # Freeze first row
    ws_md.freeze_panes = 'A2'

    # Auto-size MetaData columns
    for col_idx, col_name in enumerate(METADATA_COLUMNS, 1):
        max_len = len(col_name)
        for row_idx in range(2, len(json_data) + 2):
            cell_val = str(ws_md.cell(row=row_idx, column=col_idx).value or "")
            lines = cell_val.split('\n')
            for line in lines:
                if len(line) > max_len:
                    max_len = len(line)
        adjusted_width = min(max_len + 4, 80)
        ws_md.column_dimensions[get_column_letter(col_idx)].width = max(adjusted_width, 12)

    # Set MetaData sheet to veryHidden
    ws_md.sheet_state = 'veryHidden'

    # Save workbook
    wb.save(output_path)
    print(f"Workbook saved: {output_path}")
    print(f"File size: {os.path.getsize(output_path)} bytes")

    # Validate
    wb2 = load_workbook(output_path)
    sheets = wb2.sheetnames
    print(f"Sheets: {sheets}")
    assert 'TestPlan' in sheets, "TestPlan sheet missing"
    assert 'MetaData' in sheets, "MetaData sheet missing"
    tp_rows = wb2['TestPlan'].max_row - 1
    md_rows = wb2['MetaData'].max_row - 1
    print(f"TestPlan rows: {tp_rows}, MetaData rows: {md_rows}")
    assert tp_rows == 4, f"Expected 4 TestPlan rows, got {tp_rows}"
    assert md_rows == 4, f"Expected 4 MetaData rows, got {md_rows}"
    print("VALIDATION PASSED")
    return True

if __name__ == '__main__':
    script_dir = os.path.dirname(os.path.abspath(__file__))
    output_file = os.path.join(script_dir, 'PCIE_TestPlan_20250717_120000.xlsx')
    generate_xlsx(output_file)
